import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

def check_equation(k):
    n = 2 * (k**3)
    tau_n = tau(n)
    rhs = 2 * k
    is_solution = (tau_n == rhs)
    return k, tau_n, rhs, is_solution

# Check for k = 1 through k = 10
results = []
for k in range(1, 11):
    k_val, tau_val, rhs_val, solution = check_equation(k)
    results.append({
        'k': k_val,
        'tau(2k^3)': tau_val,
        '2k': rhs_val,
        'satisfies': solution
    })

print("k | tau(2k^3) | 2k | Satisfies")
print("-" * 35)
for res in results:
    print(f"{res['k']} | {res['tau(2k^3)']} | {res['2k']} | {res['satisfies']}")
